import json
import glob
import os
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from matplotlib.ticker import PercentFormatter
from pathlib import Path

sns.set_theme(style="whitegrid")
plt.rcParams['axes.unicode_minus'] = False
plt.rcParams['font.family'] = ['DejaVu Sans', 'sans-serif']

def load_cache_data(data_dir):
    """
    Load data and extract Cache-related diff information.
    """
    cache_records = []

    files = glob.glob(os.path.join(data_dir, "analyze_*.json")) # Assumes files still use this naming pattern, or change to *.json
    print(f"Found {len(files)} files. Loading Cache Data...")

    for file_path in files:
        try:
            filename = Path(file_path).stem
            iteration_id = filename.split('_')[1] if '_' in filename else filename

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if not content: continue
                data = json.loads(content)

            for key, result in data.items():
                if not key.startswith("cache:"):
                    continue

                resolver_name = key.replace("cache:", "")
                if result.get("status") != "success":
                    continue

                diff = result.get("diff") or {}
                summary = diff.get("summary") or {}

                # Basic counts
                added_cnt = summary.get("added", 0)
                modified_cnt = summary.get("modified", 0)
                removed_cnt = summary.get("removed", 0)

                # Derived metrics
                total_churn = added_cnt + modified_cnt + removed_cnt
                net_growth = added_cnt - removed_cnt
                modify_ratio = modified_cnt / total_churn if total_churn > 0 else 0

                # Deep analysis of Added records
                rtypes_added = {}
                max_ttl = 0
                for record in diff.get("added", []):
                    rtype = record.get("rtype", "UNKNOWN")
                    rtypes_added[rtype] = rtypes_added.get(rtype, 0) + 1
                    max_ttl = max(max_ttl, record.get("original_ttl", 0))

                # Deep analysis of Modified records
                rtypes_modified = {}
                for record in diff.get("modified", []):
                    rtype = record.get("rtype", "UNKNOWN")
                    rtypes_modified[rtype] = rtypes_modified.get(rtype, 0) + 1

                # Build flattened data row
                row = {
                    "iteration": iteration_id,
                    "resolver": resolver_name,
                    "added": added_cnt,
                    "modified": modified_cnt,
                    "removed": removed_cnt,
                    "total_churn": total_churn,
                    "net_growth": net_growth,
                    "modify_ratio": modify_ratio,
                    "max_ttl": max_ttl
                }
                # Add RTYPE distribution as columns (e.g., column names RTYPE_A, RTYPE_AAAA)
                for rt, cnt in rtypes_added.items():
                    row[f"RTYPE_ADDED_{rt}"] = cnt

                # Add Modified RTYPE distribution as columns
                for rt, cnt in rtypes_modified.items():
                    row[f"RTYPE_MODIFIED_{rt}"] = cnt

                cache_records.append(row)

        except Exception as e:
            print(f"Warning: Error processing {file_path}: {str(e)}")

    df = pd.DataFrame(cache_records)
    # Fill NaN values generated by RTYPE columns
    df = df.fillna(0)
    return df

def viz_1_cache_churn_stack(df_cache, output_dir):
    """1. Cache Activity Composition (Added / Modified / Removed) Stacked Chart"""
    if df_cache.empty: return

    # Calculate average add/delete/modify counts per resolver
    stats = df_cache.groupby('resolver')[['added', 'modified', 'removed']].mean()

    ax = stats.plot(kind='bar', stacked=True, figsize=(10, 6), color=['#2ecc71', '#f1c40f', '#e74c3c'])

    # Remove title
    # plt.title('Average Cache Churn per Query')
    plt.ylabel('Number of Records')
    plt.xlabel('Resolver')
    # Place x-axis labels horizontally
    plt.xticks(rotation=0)
    # Remove grid
    ax.grid(False)
    # Remove top and right borders
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    plt.legend(['Added', 'Modified', 'Removed'], title="Action")

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_1_churn_stack.pdf'), format='pdf', dpi=300)
    plt.close()

def viz_2_net_growth_and_modify_ratio(df_cache, output_dir):
    """2. Net Cache Growth (bars) vs Refresh Ratio (line) dual-axis chart"""
    if df_cache.empty: return

    stats = df_cache.groupby('resolver')[['net_growth', 'modify_ratio']].mean().reset_index()

    fig, ax1 = plt.subplots(figsize=(10, 6))

    # Left axis: net growth
    sns.barplot(data=stats, x='resolver', y='net_growth', ax=ax1, color='#3498db', alpha=0.7)
    ax1.set_ylabel('Avg Net Cache Growth')
    ax1.set_xlabel('Resolver')

    # Right axis: refresh ratio
    ax2 = ax1.twinx()
    sns.pointplot(data=stats, x='resolver', y='modify_ratio', ax=ax2, color='#e67e22', markers='D')
    ax2.set_ylabel('Avg Modify Ratio')
    ax2.set_ylim(0, max(stats['modify_ratio'].max() * 1.2, 0.1)) # Leave space at the top

    ax2.yaxis.set_major_formatter(PercentFormatter(1.0))

    plt.title('Net Growth vs Freshening Aggressiveness')

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_2_growth_and_refresh.png'), dpi=300)
    plt.close()

def viz_3_added_rtype_distribution(df_cache, output_dir):
    """3. Added Cache RTYPE Distribution Comparison"""
    if df_cache.empty: return

    # Filter all columns starting with RTYPE_ADDED_
    rtype_cols = [col for col in df_cache.columns if col.startswith("RTYPE_ADDED_")]
    if not rtype_cols: return

    # Calculate average of each RTYPE
    stats = df_cache.groupby('resolver')[rtype_cols].mean()

    # Convert to percentages for chart aesthetics
    stats_pct = stats.div(stats.sum(axis=1), axis=0)

    # Clean column names RTYPE_ADDED_A -> A
    stats_pct.columns = [c.replace("RTYPE_ADDED_", "") for c in stats_pct.columns]

    ax = stats_pct.plot(kind='bar', stacked=True, figsize=(12, 7), colormap='tab20')

    plt.title('Added Cache RTYPE Distribution')
    plt.ylabel('Ratio')
    plt.xlabel('Resolver')
    plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left', title="Record Type")

    # Annotate blocks larger than 5%
    for c in ax.containers:
        labels = [f'{v.get_height():.1%}' if v.get_height() > 0.05 else '' for v in c]
        ax.bar_label(c, labels=labels, label_type='center', fontsize=8, color='white')

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_3_rtype_dist.png'), dpi=300)
    plt.close()

