def viz_5_max_ttl_observed(df_cache, output_dir):
    """5. Observed Maximum Allowed TTL (Upper Bound Truncation Strategy)"""
    if df_cache.empty: return

    # Since we're looking for the policy upper bound, take the maximum value observed across all tests for this resolver
    stats = df_cache.groupby('resolver')['max_ttl'].max().reset_index()

    plt.figure(figsize=(10, 6))
    sns.barplot(data=stats, x='resolver', y='max_ttl', color='#9b59b6')

    plt.title('Observed Maximum TTL (Seconds)')
    plt.ylabel('Max TTL')
    plt.xlabel('Resolver')

    # Add horizontal reference lines (common TTLs, e.g., 24 hours, 48 hours, 6 days)
    plt.axhline(86400, color='r', linestyle='--', alpha=0.5, label='1 Day (86400s)')
    plt.axhline(172800, color='b', linestyle='--', alpha=0.5, label='2 Days (172800s)')
    plt.axhline(518400, color='g', linestyle='--', alpha=0.5, label='6 Days (Root NS)')

    plt.legend()
    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_5_max_ttl.png'), dpi=300)
    plt.close()

def parse_dns_flags(flags):
    """Parse DNS flags bits"""
    return {
        'QR': (flags >> 15) & 1,
        'OPCODE': (flags >> 11) & 0xF,
        'AA': (flags >> 10) & 1,  # Authoritative Answer
        'TC': (flags >> 9) & 1,
        'RD': (flags >> 8) & 1,
        'RA': (flags >> 7) & 1,
        'AD': (flags >> 5) & 1,  # Authentic Data (DNSSEC)
        'CD': (flags >> 4) & 1,
        'RCODE': flags & 0xF
    }

def load_cache_policy_data(data_dir):
    """
    Load cache policy related data: trigger info, flags, authorities/additionals processing, etc.
    """
    policy_records = []

    files = glob.glob(os.path.join(data_dir, "analyze_*.json"))
    print(f"Found {len(files)} files. Loading Cache Policy Data...")

    for file_path in files:
        try:
            filename = Path(file_path).stem
            iteration_id = filename.split('_')[1] if '_' in filename else filename

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if not content: continue
                data = json.loads(content)

            for key, result in data.items():
                if not key.startswith("cache:"):
                    continue

                resolver_name = key.replace("cache:", "")
                if result.get("status") != "success":
                    continue

                diff = result.get("diff") or {}
                trigger = diff.get("trigger") or {}

                if not trigger:
                    continue

                # Parse flags
                flags = trigger.get("flags", 0)
                parsed_flags = parse_dns_flags(flags)

                # Records in trigger
                answers = trigger.get("answers", [])
                authorities = trigger.get("authorities", [])
                additionals = trigger.get("additionals", [])
                non_opt_additionals = [a for a in additionals if a.get("type") != "OPT"]

                # Records in cache
                added = diff.get("added", [])
                modified = diff.get("modified", [])

                # Count negative cache
                neg_count = sum(1 for r in added if r.get("is_neg"))

                # Count rtypes in trigger
                trigger_rtypes = {}
                for r in answers + authorities + non_opt_additionals:
                    rtype = r.get("type", "UNKNOWN")
                    trigger_rtypes[rtype] = trigger_rtypes.get(rtype, 0) + 1

                # Count rtypes in added
                added_rtypes = {}
                for r in added:
                    rtype = r.get("rtype", "UNKNOWN")
                    added_rtypes[rtype] = added_rtypes.get(rtype, 0) + 1

                # Count rtypes and modification types in modified
                modified_rtypes = {}
                ttl_changes = 0
                rdata_changes = 0
                for m in modified:
                    old = m.get("old", {})
                    new = m.get("new", {})
                    rtype = old.get("rtype", "UNKNOWN")
                    modified_rtypes[rtype] = modified_rtypes.get(rtype, 0) + 1

                    if old.get("ttl") != new.get("ttl"):
                        ttl_changes += 1
                    if old.get("rdata") != new.get("rdata"):
                        rdata_changes += 1

                # Build record
                row = {
                    "iteration": iteration_id,
                    "resolver": resolver_name,
                    "flags_aa": parsed_flags["AA"],
                    "flags_ad": parsed_flags["AD"],
                    "flags_rcode": parsed_flags["RCODE"],
                    "trigger_answers": len(answers),
                    "trigger_authorities": len(authorities),
                    "trigger_additionals": len(non_opt_additionals),
                    "cached_added": len(added),
                    "cached_modified": len(modified),
                    "neg_cache_count": neg_count,
                    "ttl_changes": ttl_changes,
                    "rdata_changes": rdata_changes,
                }

                # Add rtype statistics
                for rt, cnt in trigger_rtypes.items():
                    row[f"TRIGGER_RTYPE_{rt}"] = cnt
                for rt, cnt in added_rtypes.items():
                    row[f"CACHED_RTYPE_{rt}"] = cnt
                for rt, cnt in modified_rtypes.items():
                    row[f"MODIFIED_RTYPE_{rt}"] = cnt

                policy_records.append(row)

        except Exception as e:
            print(f"Warning: Error processing {file_path}: {str(e)}")

    df = pd.DataFrame(policy_records)
    df = df.fillna(0)
    return df

def load_modified_detail_data(data_dir):
    """
    Load detailed data of modified records for TTL refresh strategy analysis
    """
    modified_records = []

    files = glob.glob(os.path.join(data_dir, "analyze_*.json"))

    for file_path in files:
        try:
            filename = Path(file_path).stem
            iteration_id = filename.split('_')[1] if '_' in filename else filename

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if not content: continue
                data = json.loads(content)

            for key, result in data.items():
                if not key.startswith("cache:"):
                    continue

                resolver_name = key.replace("cache:", "")
                if result.get("status") != "success":
                    continue

                diff = result.get("diff") or {}
                modified = diff.get("modified", [])

                for m in modified:
                    old = m.get("old", {})
                    new = m.get("new", {})

                    # Calculate TTL change
                    old_ttl = old.get("ttl", 0)
                    new_ttl = new.get("ttl", 0)
                    ideal = m.get("ideal", 0)
                    actual = m.get("actual", 0)

                    # TTL refresh deviation
                    if ideal and ideal > 0:
                        ttl_deviation = actual - ideal
                        ttl_deviation_ratio = ttl_deviation / ideal
                    else:
                        ttl_deviation = 0
                        ttl_deviation_ratio = 0

                    row = {
                        "iteration": iteration_id,
                        "resolver": resolver_name,
                        "rtype": old.get("rtype", "UNKNOWN"),
                        "name": old.get("name", ""),
                        "old_ttl": old_ttl,
                        "new_ttl": new_ttl,
                        "ideal_ttl": ideal,
                        "actual_ttl": actual,
                        "ttl_deviation": ttl_deviation,
                        "ttl_deviation_ratio": ttl_deviation_ratio,
                        "is_neg": old.get("is_neg", False),
                        "rdata_changed": old.get("rdata") != new.get("rdata"),
                    }
                    modified_records.append(row)

        except Exception as e:
            pass

    df = pd.DataFrame(modified_records)
    return df

