def viz_9_ttl_refresh_deviation(df_modified, output_dir):
    """9. TTL Refresh Deviation Analysis"""
    if df_modified.empty: return

    # Filter valid data
    valid_df = df_modified[df_modified['ideal_ttl'] > 0].copy()
    if valid_df.empty: return

    # Calculate TTL deviation by resolver
    stats = valid_df.groupby('resolver').agg({
        'ttl_deviation': ['mean', 'std', 'min', 'max'],
        'ttl_deviation_ratio': ['mean', 'std']
    }).reset_index()
    stats.columns = ['resolver', 'avg_dev', 'std_dev', 'min_dev', 'max_dev',
                     'avg_ratio', 'std_ratio']

    fig, axes = plt.subplots(1, 2, figsize=(12, 5))

    # Left chart: absolute deviation
    sns.barplot(data=stats, x='resolver', y='avg_dev', ax=axes[0],
               color='#e74c3c', alpha=0.7)
    axes[0].errorbar(range(len(stats)), stats['avg_dev'],
                    yerr=stats['std_dev'], fmt='k_', capsize=5)
    axes[0].set_title('Avg TTL Refresh Deviation (sec)')
    axes[0].set_ylabel('Deviation (sec)')
    axes[0].set_xlabel('Resolver')

    # Right chart: relative deviation ratio
    sns.barplot(data=stats, x='resolver', y='avg_ratio', ax=axes[1],
               color='#f39c12', alpha=0.7)
    axes[1].errorbar(range(len(stats)), stats['avg_ratio'],
                    yerr=stats['std_ratio'], fmt='k_', capsize=5)
    axes[1].set_title('Avg TTL Refresh Deviation Ratio')
    axes[1].set_ylabel('Deviation Ratio')
    axes[1].set_xlabel('Resolver')

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_9_ttl_deviation.png'), dpi=300)
    plt.close()

def viz_10_resolver_comparison_summary(df_policy, output_dir):
    """10. Resolver Cache Policy Comprehensive Comparison"""
    if df_policy.empty: return

    # Comprehensive statistics
    stats = df_policy.groupby('resolver').agg({
        'cached_added': 'mean',
        'cached_modified': 'mean',
        'neg_cache_count': 'mean',
        'ttl_changes': 'sum',
    }).reset_index()

    # Create heatmap-style data
    metrics = ['cached_added', 'cached_modified', 'neg_cache_count', 'ttl_changes']
    stats_normalized = stats.copy()
    for m in metrics:
        max_val = stats[m].max()
        if max_val > 0:
            stats_normalized[m] = stats[m] / max_val

    fig, ax = plt.subplots(figsize=(10, 6))

    # Plot grouped bar chart
    data_for_plot = stats_normalized.set_index('resolver')[metrics]

    # Rename columns
    data_for_plot.columns = [
        'Avg Added',
        'Avg Modified',
        'Avg Neg Cache',
        'Total TTL Chg'
    ]

    sns.heatmap(data_for_plot, annot=True, fmt='.2f', cmap='YlOrRd',
               ax=ax, linewidths=0.5)

    ax.set_title('Resolver Cache Policy Comparison (Normalized)')

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_10_policy_summary.png'), dpi=300)
    plt.close()

def load_resolver_path_data(data_dir):
    """
    Load detailed data from resolver's analyzed_path, analyze the association between response records and cache
    """
    path_records = []

    files = glob.glob(os.path.join(data_dir, "analyze_*.json"))
    print(f"Found {len(files)} files. Loading Resolver Path Data...")

    for file_path in files:
        try:
            filename = Path(file_path).stem
            iteration_id = filename.split('_')[1] if '_' in filename else filename

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if not content: continue
                data = json.loads(content)

            # Get cache data for association
            cache_data = {}
            for key in data:
                if key.startswith("cache:"):
                    resolver = key.replace("cache:", "")
                    cache_data[resolver] = data[key].get('diff', {})

            # Analyze resolver data
            for key in data:
                if key.startswith("resolver:"):
                    resolver_name = key.replace("resolver:", "")
                    transaction = data[key].get('transaction', {})
                    path = transaction.get('analyzed_path', {})
                    steps = path.get('steps', [])

                    # Get corresponding cache data
                    cache_diff = cache_data.get(resolver_name, {})
                    added_records = cache_diff.get('added', [])
                    modified_records = cache_diff.get('modified', [])

                    # Create cache record index (name + rtype)
                    # added: newly added cache records
                    added_index = {(r.get('name'), r.get('rtype')) for r in added_records}
                    # modified.old: original records that were modified (used to determine if modified)
                    modified_old_index = {(r.get('name'), r.get('rtype')) for r in modified_records}
                    # modified.new: modified records (also part of current cache state)
                    modified_new_index = {(m.get('new', {}).get('name'), m.get('new', {}).get('rtype')) for m in modified_records}

                    # Combined cache index: added + modified.new are both current cache state
                    cached_index = added_index | modified_new_index

                    for step_idx, step in enumerate(steps):
                        resp = step.get('response', {})
                        if not resp:
                            continue

                        flags = resp.get('flags', 0)
                        parsed_flags = parse_dns_flags(flags)

                        answers = resp.get('answers', [])
                        authorities = resp.get('authorities', [])
                        additionals = resp.get('additionals', [])
                        non_opt_additionals = [a for a in additionals if a.get('type') != 'OPT']

                        # Count records by category
                        for record_type, records in [
                            ('answer', answers),
                            ('authority', authorities),
                            ('additional', non_opt_additionals)
                        ]:
                            for rec in records:
                                name = rec.get('name', '')
                                rtype = rec.get('type', 'UNKNOWN')
                                ttl = rec.get('ttl', 0)

                                # Cache status: in added or modified.new
                                is_cached = (name, rtype) in cached_index
                                # Specific cache type
                                is_cached_added = (name, rtype) in added_index
                                is_cached_modified = (name, rtype) in modified_old_index

                                row = {
                                    "iteration": iteration_id,
                                    "resolver": resolver_name,
                                    "step_idx": step_idx,
                                    "record_type": record_type,
                                    "name": name,
                                    "rtype": rtype,
                                    "ttl": ttl,
                                    "flags_aa": parsed_flags['AA'],
                                    "flags_ad": parsed_flags['AD'],
                                    "flags_rcode": parsed_flags['RCODE'],
                                    "is_cached": is_cached,
                                    "is_cached_added": is_cached_added,
                                    "is_cached_modified": is_cached_modified,
                                }
                                path_records.append(row)

        except Exception as e:
            pass

    df = pd.DataFrame(path_records)
    return df

def viz_11_response_record_cache_rate(df_path, output_dir):
    """11. Response Record Cache Rate Comparison (Answers/Authorities/Additionals)"""
    if df_path.empty: return

    # Calculate cache rate by resolver and record_type
    # is_cached = is_cached_added OR is_cached_modified (in added or modified.new)
    stats = df_path.groupby(['resolver', 'record_type']).agg({
        'is_cached': ['sum', 'count'],
    }).reset_index()
    stats.columns = ['resolver', 'record_type', 'cached_count', 'total_count']
    stats['cache_rate'] = stats['cached_count'] / stats['total_count']

    fig, ax = plt.subplots(figsize=(12, 6))

    record_types = ['answer', 'authority', 'additional']
    colors = ['#3498db', '#e67e22', '#9b59b6']
    x = range(len(stats['resolver'].unique()))
    width = 0.25

    for i, (rt, color) in enumerate(zip(record_types, colors)):
        rt_stats = stats[stats['record_type'] == rt]
        ax.bar([xi + i * width - width for xi in x],
               rt_stats['cache_rate'].values,
               width, label=rt.capitalize(), color=color, alpha=0.7)

    ax.set_xlabel('Resolver')
    ax.set_ylabel('Cache Rate')
    ax.set_title('Response Record Cache Rate Comparison')
    ax.set_xticks(x)
    ax.set_xticklabels(stats['resolver'].unique())
    ax.legend()

    # Add percentage labels
    ax.yaxis.set_major_formatter(PercentFormatter(1.0))
    ax.set_ylim(0, 1)

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_11_response_cache_rate.png'), dpi=300)
    plt.close()

def viz_12_aa_ad_cache_rate(df_path, output_dir):
    """12. AA/AD-flagged Record Cache Rate"""
    if df_path.empty: return

    fig, axes = plt.subplots(1, 2, figsize=(14, 6))

    # AA-flagged record cache rate
    aa_records = df_path[df_path['flags_aa'] == 1]
    if not aa_records.empty:
        aa_stats = aa_records.groupby('resolver').agg({
            'is_cached': ['sum', 'count']
        }).reset_index()
        aa_stats.columns = ['resolver', 'cached', 'total']
        aa_stats['rate'] = aa_stats['cached'] / aa_stats['total']

        sns.barplot(data=aa_stats, x='resolver', y='rate', ax=axes[0],
                   color='#2ecc71', alpha=0.7)
        axes[0].set_title('AA-flagged Record Cache Rate')
        axes[0].set_ylabel('Cache Rate')
        axes[0].set_xlabel('Resolver')
        axes[0].yaxis.set_major_formatter(PercentFormatter(1.0))

        # Add value labels
        for i, row in aa_stats.iterrows():
            axes[0].text(i, row['rate'] + 0.02, f'{row["rate"]:.1%}',
                        ha='center', va='bottom', fontsize=9)

    # AD-flagged record cache rate
    ad_records = df_path[df_path['flags_ad'] == 1]
    if not ad_records.empty:
        ad_stats = ad_records.groupby('resolver').agg({
            'is_cached': ['sum', 'count']
        }).reset_index()
        ad_stats.columns = ['resolver', 'cached', 'total']
        ad_stats['rate'] = ad_stats['cached'] / ad_stats['total']

        sns.barplot(data=ad_stats, x='resolver', y='rate', ax=axes[1],
                   color='#f39c12', alpha=0.7)
        axes[1].set_title('AD-flagged Record Cache Rate')
        axes[1].set_ylabel('Cache Rate')
        axes[1].set_xlabel('Resolver')
        axes[1].yaxis.set_major_formatter(PercentFormatter(1.0))

        for i, row in ad_stats.iterrows():
            axes[1].text(i, row['rate'] + 0.02, f'{row["rate"]:.1%}',
                        ha='center', va='bottom', fontsize=9)

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_12_aa_ad_cache_rate.png'), dpi=300)
    plt.close()

def viz_13_rtype_cache_rate_by_section(df_path, output_dir):
    """13. Cache Trigger Rate by RTYPE in Each Section"""
    if df_path.empty: return

    # Filter main rtypes
    main_rtypes = ['A', 'AAAA', 'NS', 'SOA', 'CNAME']

    fig, axes = plt.subplots(1, 3, figsize=(15, 5))

    for idx, (section, title) in enumerate([
        ('answer', 'Answers'),
        ('authority', 'Authorities'),
        ('additional', 'Additionals')
    ]):
        section_df = df_path[df_path['record_type'] == section]
        if section_df.empty:
            axes[idx].text(0.5, 0.5, 'No Data', ha='center', va='center')
            continue

        # Calculate cache trigger rate by rtype
        rtype_stats = section_df.groupby(['resolver', 'rtype']).agg({
            'is_cached': ['sum', 'count']
        }).reset_index()
        rtype_stats.columns = ['resolver', 'rtype', 'cached', 'total']
        rtype_stats['rate'] = rtype_stats['cached'] / rtype_stats['total']

        # Show only main rtypes
        rtype_stats = rtype_stats[rtype_stats['rtype'].isin(main_rtypes)]

        if not rtype_stats.empty:
            sns.barplot(data=rtype_stats, x='rtype', y='rate', hue='resolver',
                       ax=axes[idx], alpha=0.7)
            axes[idx].set_title(title)
            axes[idx].set_ylabel('Cache Trigger Rate')
            axes[idx].set_xlabel('Record Type')
            axes[idx].yaxis.set_major_formatter(PercentFormatter(1.0))
            axes[idx].legend(loc='upper right', fontsize=8)

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_13_rtype_by_section.png'), dpi=300)
    plt.close()

def viz_14_resolver_policy_heatmap(df_path, output_dir):
    """14. Resolver Cache Policy Comprehensive Heatmap"""
    if df_path.empty: return

    # Calculate various metrics
    metrics = []

    for resolver in df_path['resolver'].unique():
        res_df = df_path[df_path['resolver'] == resolver]

        # Answers cache trigger rate
        answers = res_df[res_df['record_type'] == 'answer']
        answers_rate = answers['is_cached'].mean() if not answers.empty else 0

        # Authorities cache trigger rate
        authorities = res_df[res_df['record_type'] == 'authority']
        authorities_rate = authorities['is_cached'].mean() if not authorities.empty else 0

        # Additionals cache trigger rate
        additionals = res_df[res_df['record_type'] == 'additional']
        additionals_rate = additionals['is_cached'].mean() if not additionals.empty else 0

        # AA cache trigger rate
        aa_records = res_df[res_df['flags_aa'] == 1]
        aa_rate = aa_records['is_cached'].mean() if not aa_records.empty else 0

        # AD cache trigger rate
        ad_records = res_df[res_df['flags_ad'] == 1]
        ad_rate = ad_records['is_cached'].mean() if not ad_records.empty else 0

        metrics.append({
            'resolver': resolver,
            'answers_rate': answers_rate,
            'authorities_rate': authorities_rate,
            'additionals_rate': additionals_rate,
            'aa_rate': aa_rate,
            'ad_rate': ad_rate
        })

    metrics_df = pd.DataFrame(metrics)
    metrics_df = metrics_df.set_index('resolver')

    # Rename columns
    metrics_df.columns = [
        'Answers Trigger',
        'Authorities Trigger',
        'Additionals Trigger',
        'AA Trigger',
        'AD Trigger'
    ]

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.heatmap(metrics_df, annot=True, fmt='.2%', cmap='RdYlGn',
               ax=ax, linewidths=0.5, vmin=0, vmax=1)

    ax.set_title('Resolver Cache Policy Comparison')

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_14_policy_heatmap.png'), dpi=300)
    plt.close()

def viz_15_aa_ad_response_stats(df_path, output_dir):
    """15. AA/AD Response Statistics"""
    if df_path.empty: return

    # Count AA/AD responses per resolver
    # Count each step only once (not per record)
    step_stats = df_path.groupby(['resolver', 'iteration', 'step_idx']).agg({
        'flags_aa': 'max',  # All records in the same step have identical flags
        'flags_ad': 'max'
    }).reset_index()

    # Count AA/AD response quantity
    resp_stats = step_stats.groupby('resolver').agg({
        'flags_aa': 'sum',
        'flags_ad': 'sum',
        'step_idx': 'count'  # Total response count
    }).reset_index()
    resp_stats.columns = ['resolver', 'aa_responses', 'ad_responses', 'total_responses']

    fig, axes = plt.subplots(1, 2, figsize=(12, 5))

    # AA Response ratio
    resp_stats['aa_ratio'] = resp_stats['aa_responses'] / resp_stats['total_responses']
    sns.barplot(data=resp_stats, x='resolver', y='aa_ratio', ax=axes[0],
               color='#27ae60', alpha=0.7)
    axes[0].set_title('AA Response Ratio')
    axes[0].set_ylabel('Ratio')
    axes[0].set_xlabel('Resolver')
    axes[0].yaxis.set_major_formatter(PercentFormatter(1.0))

    # AD Response ratio
    resp_stats['ad_ratio'] = resp_stats['ad_responses'] / resp_stats['total_responses']
    sns.barplot(data=resp_stats, x='resolver', y='ad_ratio', ax=axes[1],
               color='#e74c3c', alpha=0.7)
    axes[1].set_title('AD Response Ratio')
    axes[1].set_ylabel('Ratio')
    axes[1].set_xlabel('Resolver')
    axes[1].yaxis.set_major_formatter(PercentFormatter(1.0))

    plt.tight_layout()
    plt.savefig(os.path.join(output_dir, 'cache_15_aa_ad_response_stats.png'), dpi=300)
    plt.close()

